from collections import deque

def get_reachable_regions(grid, fill_val):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    regions = []

    # Flood from border
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == fill_val:
                if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                    queue.append((r,c))
                    visited[r][c] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0<=nr<rows and 0<=nc<cols and not visited[nr][nc] and grid[nr][nc]==fill_val:
                visited[nr][nc] = True
                queue.append((nr,nc))

    # Group into regions
    regions = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == fill_val and not visited[r][c]:
                # This is an unvisited (enclosed) region
                region = []
                queue2 = deque([(r,c)])
                visited[r][c] = True
                while queue2:
                    cr, cc = queue2.popleft()
                    region.append((cr, cc))
                    for dr2, dc2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ncrc, nccc = cr+dr2, cc+dc2
                        if 0<=ncrc<rows and 0<=nccc<cols and not visited[ncrc][nccc] and grid[ncrc][nccc]==fill_val:
                            visited[ncrc][nccc] = True
                            queue2.append((ncrc,nccc))
                regions.append(('enclosed', region))

    return visited, regions

